window.TRACE_DECK = {"content":{"_ai_assisted":"AI-assisted: written with Claude Code (Anthropic) and maintained with Codex (OpenAI). See docs/AI_USAGE.md.","_note":"Source of truth for the TRACE pitch deck. Edit here, then run: python3 deck/build.py","meta":{"title":"TRACE","event":"2026 Carolina Data Challenge · Graduate Track","theme":"AI for Social Good","runtime_target_seconds":270,"demo_seconds":120,"qa_seconds":120,"format_note":"5:00 maximum, three speakers (Problem · Data · Technical architecture), then Q&A. Backup slides after the close are for Q&A only and are not timed."},"speakers":[{"slot":"S1","name":"William Keffer","section":"The Problem","seconds":70},{"slot":"S2","name":"Ismail Gasmi","section":"The Data","seconds":75},{"slot":"S3","name":"Markandeya Yalamanchi","section":"Technical Architecture","seconds":125},{"slot":"S4","name":"Adrian Hito","section":"Technical Q&A","seconds":0}],"slides":[{"id":"title","act":"I","speaker":"S1","seconds":0,"theme":"void","layout":"split","blocks":[{"type":"qr","src":"assets/qr-trace-site.svg","caption":"Scan to open the live site","url":"trace-atlas-gules.vercel.app"},{"type":"wordmark","text":"TRACE"},{"type":"lines","scale":"m","items":["{{project.one_liner}}"]},{"type":"source","text":"2026 Carolina Data Challenge · Graduate Track · AI for Social Good"}],"cues":["Leave this up while judges settle in; it gives them time to scan the code.","Advance to the Afghanistan slide to start the clock."]},{"id":"cold-1","act":"I","speaker":"S1","seconds":10,"theme":"void","blocks":[{"type":"photo","variant":"side","src":"assets/slide-1-afghanistan-opium.jpg","alt":"An armed man carrying a rocket launcher walks through a flowering opium poppy field in Afghanistan.","caption":"AFGHANISTAN · OPIUM POPPY FIELD · 2005 FILE PHOTO"},{"type":"lines","scale":"xl","items":["Afghanistan grew four fifths","of the world's illicit opium."]},{"type":"viz","viz":{"kind":"fraction","parts":5,"filled":4,"label":"4 of every 5 kilograms of illicit opium on earth · before 2022"}},{"type":"source","text":"UNODC World Drug Report 2026 · about 80% of global illicit opium production before 2022"}],"cues":["Hold two full seconds of silence before you speak.","Say it flat. The fact does the work.","Four fifths. Not 'most' — the number is the hook.","The photo is a 2005 file image of an Afghan opium poppy field; it sets the scene, it is not TRACE evidence. Photographer credit and reuse permission still need to be confirmed."],"layout":"split"},{"id":"cold-2","act":"I","speaker":"S1","seconds":8,"theme":"void","blocks":[{"type":"lines","scale":"xl","items":["In April 2022, one decree"]},{"type":"lines","scale":"xl","tone":"accent","items":["cut it by 95%."]},{"type":"viz","viz":{"kind":"bars","size":"big","items":[{"label":"2022","value":6200,"text":"6,200 t","tone":"off"},{"label":"2023","value":333,"text":"333 t","tone":"on"}]},"caption":"Afghan opium production, tonnes"},{"type":"source","text":"Taliban decree 3 April 2022, enforced from the 2022/23 planting season · Afghan opium production 6,200 t (2022) → 333 t (2023) · UNODC Afghanistan Opium Survey"}],"cues":["Beat before '95%'.","Be precise if asked: 95% is Afghan *production*, and Afghanistan was ~80% of world supply.","Never say 'erased the world's opium' — about 12,000 tonnes of stockpile kept flowing."]},{"id":"cold-3","act":"I","speaker":"S1","seconds":7,"theme":"void","blocks":[{"type":"lines","scale":"l","items":["The drugs didn't stop."]},{"type":"lines","scale":"xl","tone":"accent","items":["They moved."],"step":1},{"type":"sub","text":"And for three years, nobody could tell the countries they moved toward that they were coming.","step":1,"stepDelay":900}],"cues":["Click once after 'The drugs didn't stop.' to bring in 'They moved.' Let the pause land.","'They moved' is the thesis of the entire project.","Land it, then go straight to the lag slide."],"layout":"center"},{"id":"lag","act":"I","speaker":"S1","seconds":14,"theme":"void","blocks":[{"type":"kicker","text":"The world's drug-harm data, today"},{"type":"lagrow","items":[{"label":"Intentional homicide rate","year":"2022","code":"VC.IHR.PSRC.P5 · 142 of 243 have nothing newer"},{"label":"HIV incidence, 15–49","year":"2024","code":"SH.HIV.INCD.ZS · modelled, not surveyed"},{"label":"Poverty headcount","year":"2022","code":"SI.POV.DDAY · 59% have nothing newer"},{"label":"Cannabis use prevalence","year":"2017","code":"UNODC WDR annex 1.2 · 11 countries have a 2024+ estimate"}]},{"type":"lines","scale":"m","items":["Development data runs two to four years late.","Drug-use prevalence, for the median country,","runs nine."]},{"type":"source","text":"Median economy's most recent value, World Bank Indicators API, retrieved 2026-09-26 · UNODC World Drug Report 2026 statistical annex"}],"cues":["These are median-country figures we pulled from the live API, not the best-reported country.","Nine years is the number to land. Say it and stop.","If challenged: the WDR headline year is 2024, but that rests on estimates most countries last made in 2017."]},{"id":"late-detection","act":"I","speaker":"S1","seconds":16,"theme":"void","blocks":[{"type":"photo","variant":"backdrop","src":"assets/slide-5-austin-march.jpg","alt":"Austin residents march during the 2015 Scott County HIV emergency; a memorial sign is visible.","caption":"AUSTIN · 2015 · SARAH PARVINI / LOS ANGELES TIMES"},{"type":"kicker","text":"What the delay costs"},{"type":"lines","scale":"l","items":["Scott County, Indiana.","HIV spread undetected for four years."]},{"type":"statgrid","compact":true,"items":[{"value":"215","label":"people infected","source":"undetected from 2011; emergency declared 26 March 2015","viz":{"kind":"dots","count":215,"per":1,"label":"one dot = one person"}},{"value":"<56","label":"if caught in 2013","source":"modelled counterfactual","viz":{"kind":"dots","count":56,"per":1}},{"value":"<10","label":"if the 2011 hepatitis C signal had been read","source":"the warning was already in the data","viz":{"kind":"dots","count":10,"per":1}}]},{"type":"sub","text":"This is the pattern, not the exception. In three of four documented outbreaks a hepatitis C or injecting signal preceded the HIV outbreak by one to four years and was not collected, not analysed, or not acted on. Across the modelled outbreaks, <em>60 to 95 percent</em> of infections are attributed to the delay in detection and response — not to the drugs."},{"type":"source","text":"Glasgow 2015: 62.7% of cases averted had services scaled at detection · Athens: HIV among people who inject drugs rose from under 1% (2010) to 16.5% (2013); intervening two years earlier modelled to avert 1,110 cases and €35–53M"},{"type":"source","text":"Photo: Sarah Parvini / Los Angeles Times, Austin (2015) · <a href=\"https://www.latimes.com/nation/la-na-indiana-hiv-20150401-story.html\">report and caption</a> · Memorial shown concerns a separate overdose death, not an HIV-outbreak death."}],"cues":["Two sentences only. The numbers do the work.","The counterfactual is the point: almost all of that epidemic was the delay, not the drugs.","Do not editorialise. Let '<10' sit there.","The photo is a 2015 Austin community march; the memorial in frame is not an HIV-outbreak death. Keep the point on delayed public-health detection and response.","The maintainer confirmed Los Angeles Times image reuse permission is cleared for this public presentation."]},{"id":"reframe","act":"I","speaker":"S1","seconds":15,"theme":"atlas","blocks":[{"type":"swap","from":"Where are the drugs?","to":"Where does the harm land next?"},{"type":"sub","text":"Every other tool in this space answers the first question, for police. And every existing harm forecast is <em>autoregressive</em> — it predicts more of an epidemic a country already has. TRACE answers the second question, for public health, from outside: it forecasts harm in countries that have not had the epidemic yet, from the corridor that is about to open."}],"cues":["This swap is the innovation claim. Make it the loudest sentence.","Hand off: 'To forecast where harm lands, you first need data nobody had joined up.'"],"layout":"center"},{"id":"data-spine","act":"II","speaker":"S2","seconds":30,"theme":"atlas","blocks":[{"type":"kicker","text":"The data spine"},{"type":"statgrid","items":[{"value":"{{counts.indicators}}","label":"World Bank indicators","source":"Indicators API, sources 2 + 3, pulled programmatically into the SQLite v2 archive","viz":{"kind":"span","min":1960,"max":2025,"label":"1960–2025","from":1960,"to":2025}},{"value":"{{counts.economies}}","label":"economies","source":"SQLite v2 archive, 1960–2025; aggregates filtered out","viz":{"kind":"span","min":1960,"max":2025,"label":"1960–2025","from":1960,"to":2025}},{"value":"{{counts.ids_cases}}","label":"UNODC seizure cases","source":"Individual Drug Seizures, 2006–2024","viz":{"kind":"span","min":1960,"max":2025,"label":"2006–2024","from":2006,"to":2024}},{"value":"{{counts.corridors}}","label":"corridors modelled","source":"× 14 years, seizure-anchored allocation","viz":{"kind":"span","min":1960,"max":2025,"label":"2011–2024","from":2011,"to":2024}},{"value":"{{counts.oc_index}}","label":"countries, OC Index","source":"GI-TOC 2021 / 2023 / 2025 editions","viz":{"kind":"span","min":1960,"max":2025,"label":"3 editions","ticks":[2021,2023,2025]}},{"value":"{{counts.hri}}","label":"countries, harm reduction","source":"Harm Reduction International, Global State of Harm Reduction, 2025 update to key data","viz":{"kind":"span","min":1960,"max":2025,"label":"2025 update","ticks":[2025]}}]},{"type":"source","text":"Live evidence drilldown traces research and derived market values to formulas, source editions, exact input rows and original URLs; health and overdose records retain their method, date and status labels."}],"cues":["Read two numbers, not six: the World Bank indicators and the UNODC seizure cases.","World Bank data plays five roles: market size (GDP, population), route friction (WGI governance, ports, air traffic, logistics), vulnerability (youth unemployment, poverty, Gini, health spend), outcomes for validation (homicide, HIV), and a detection-bias control that is fitted but never shown.","Every call is programmatic with explicit source IDs (2 and 3), paginated, nulls kept, provenance recorded."]},{"id":"honesty-method","act":"II","speaker":"S2","seconds":25,"theme":"atlas","blocks":[{"type":"kicker","text":"The objection we designed around"},{"type":"lines","scale":"m","items":["Seizures measure enforcement,","not trafficking."]},{"type":"viz","viz":{"kind":"stack","total":100,"items":[{"label":"seizures at both ends","value":30,"tone":0},{"label":"price rises along the route","value":20,"tone":1},{"label":"OC Index market score at both ends","value":20,"tone":2},{"label":"live news hits","value":10,"tone":3},{"label":"cultivation upstream","value":10,"tone":4},{"label":"documented UNODC corridor","value":10,"tone":5}],"label":"Corridor confidence, 0–100 points · seizures can supply at most 30"}},{"type":"sub","text":"Correct. So no corridor rests on seizures alone. Every edge carries a 0–100 confidence score built from six independent signals: seizures at both ends, a price gradient in the expected direction, OC Index market scores at both ends, live news hits, cultivation upstream, and a documented corridor. Detection bias is controlled with rule of law and customs efficiency. Low-confidence corridors are drawn faint, and we say so."},{"type":"source","text":"Every corridor carries a citation key, and all eleven resolve to a UNODC or EUDA publication — each checked for a live response and a matching title. A route-evidence API drills from any corridor on the map to the document it came from. Every known limitation is in docs/SYSTEM_DESIGN.md §5 and docs/BLOCKERS.md, not hidden."}],"cues":["Say the objection before a judge does: seizures measure enforcement as well as trafficking.","Answer: no corridor rests on seizures alone; every edge gets a 0-100 score from six independent signals.","Routes are allocated over 234 documented UNODC corridors; the public seizure file has no route fields."],"handoff":"So — does any of it actually work?"},{"id":"terminal-hero","act":"II","speaker":"S2","seconds":20,"theme":"atlas","blocks":[{"type":"kicker","text":"One workspace. Every corridor."},{"type":"shot","sid":"route-map","aspect":"16/9","caption":"Atlas — modelled corridor arcs coloured by drug volume, {{counts.map_first_year}}–{{counts.map_last_observed}} observed with a {{counts.map_forecast_year}} forecast; the drug-coloured arrows are the estimated local-flow layer, labelled on the map as not observed","spec":"Full-bleed Atlas capture, 1440×960, Forecast on, all substances, estimated-flow arrows visible.","maxvh":70}],"cues":["One sentence: all of it becomes one workspace, the Atlas.","Hand off: 'On top of this data we built two models.'"]},{"id":"forecast","act":"III","speaker":"S3","seconds":25,"theme":"atlas","blocks":[{"type":"kicker","text":"Model 1 · route forecast, backtested blind"},{"type":"lines","scale":"m","items":["LightGBM hurdle: will a corridor be active next year, and how much moves.","Trained through 2019, predicting 2020–2024 unseen."]},{"type":"chart","src":"assets/charts/backtest.png","alt":"Grouped bars: LightGBM hurdle beats same-as-last-year and PPML gravity on AUC (0.88 vs 0.82 vs 0.58), Spearman (0.58 vs 0.48 vs 0.38) and precision@20 (0.48 vs 0.42 vs 0.34).","caption":"8,242 training corridor-years · 3,170 test corridor-years · 46 features incl. 13 World Bank indicators per end · SHAP drivers per corridor"},{"type":"source","text":"Santos Silva & Tenreyro (2006) PPML · Ke et al. (2017) LightGBM · Lundberg & Lee (2017) SHAP"}],"cues":["'Same as last year' is the honest baseline because routes are sticky. We beat it on all three measures.","Most corridors are zero most years; that is why it is a hurdle model (classifier times regressor).","Per-drug AUC if asked: meth 0.96, heroin 0.92, cannabis 0.89, cocaine 0.79."]},{"id":"reflex","act":"III","speaker":"S3","seconds":35,"theme":"atlas","blocks":[{"type":"kicker","text":"Model 2 · Reflex, our own Jev-style news classifier"},{"type":"lines","scale":"m","items":["Official data is years late. News is minutes late."]},{"type":"pipeline","steps":[{"step":"INGEST","title":"GDELT every 15 min","text":"Drug stories worldwide, deduped. Seven typed questions per headline: event?, type, drug, origin, transit, destination, size."},{"step":"TRAIN","title":"Fine-tuned on a Colab T4","text":"An NLI cross-encoder (DeBERTa-v3-xsmall) scores each answer. Log-loss on 10,777 open + UNODC-derived examples, then 2,351 blind-verified headlines. About 7 minutes."},{"step":"CALIBRATE","title":"Temperature scaling","text":"One temperature per question type, fitted on held-out data: 80% confident means right about 80% of the time."}]},{"type":"chart","size":"s","src":"assets/charts/reflex_training.png","alt":"Held-out accuracy rises from 48.1% (untuned backbone) to 90.2% (Reflex v0.2); calibration error falls from 0.206 to 0.020.","caption":"Held-out open-dataset questions · ECE 0.020 is within the 0.02–0.03 independent tests report for Jev"}],"cues":["Why build it: Jev (TypeSafe) had a waitlist and we had no key, so we implemented the same typed-question interface on an open model. No TypeSafe code or weights.","Two numbers: accuracy 48% to 90%, calibration error 0.21 to 0.02.","Jev sits behind the same JevClassifier interface and swaps in once a key exists."]},{"id":"reflex-real","act":"III","speaker":"S3","seconds":35,"theme":"atlas","blocks":[{"type":"kicker","text":"Tested on 92 real, published headlines it never saw"},{"type":"chart","src":"assets/charts/reflex_real_news.png","alt":"Field accuracy on 92 real headlines for the keyword baseline, Reflex v0.2 and Reflex plus grounding. Grounded Reflex: is_event 91, event type 88, drug 98, origin 96, destination 85, size 93.","caption":"Per-field accuracy, % · 47 events from 5 continents + 45 hard negatives (pharma recalls, overdose statistics, drug-war film reviews)"},{"type":"chart","size":"s","src":"assets/charts/reflex_grounding.png","alt":"Grounding cuts invented entities from 21.6% (keyword) and 4.9% (Reflex) to 0%, and false events from 15.4% and 12.8% to 5.1%.","caption":"Grounding: every country, drug and size must be supported by the text, or it becomes 'not stated'"}],"cues":["Every earlier test was synthetic; this is real news, labelled by hand, never used for tuning.","Grounding means zero invented countries or drugs: a location must appear in the text (gazetteer, ports, 150k+ cities); a drug must match a synonym (shabu = meth, carfentanil = fentanyl).","Anomaly flag: a confident seizure on a corridor our forecast gave under 10% is flagged on the map; the model announces its own miss."]},{"id":"deploy","act":"III","speaker":"S3","seconds":22,"theme":"atlas","blocks":[{"type":"kicker","text":"Shipping it · ONNX export for a CPU server"},{"type":"statgrid","compact":true,"items":[{"value":"98.7%","label":"of headlines get identical Live Wire output after export","source":"150 headlines, all 7 fields, ONNX vs PyTorch"},{"value":"3.6 s","label":"model load, down from 58.9 s in PyTorch","source":"137 MB ONNX model, laptop CPU"},{"value":"0.84","label":"precision of events shown on real news, at 0.86 mean confidence","source":"calibration holds out of the lab: ECE 0.052 after grounding"}]},{"type":"sub","text":"Same answers, a fraction of the weight: Reflex runs without PyTorch, so the Live Wire can classify news on the deployed API instead of a GPU notebook."},{"type":"source","text":"backend/scripts/export_reflex_onnx.py · reflex/results/onnx_parity.json · reflex/results/real_news_v1.json"}],"cues":["Honest limits, if time: one annotator; 92 rows means wide error bars; false events 5.1% against a 5% target.","Hand to the close."]},{"id":"close","act":"IV","speaker":"S3","seconds":8,"theme":"void","blocks":[{"type":"lines","scale":"l","tone":"dim","items":["Harm reduction usually arrives","after the crisis."]},{"type":"lines","scale":"xl","tone":"accent","items":["TRACE lets it arrive before."]}],"cues":["Pause before the last line. Then stop.","Next slide is the QR; open the floor to questions."]},{"id":"handoff","act":"IV","speaker":"S3","seconds":0,"theme":"void","blocks":[{"type":"qr","src":"assets/qr-trace-site.svg","caption":"Scan to open the live site","url":"trace-atlas-gules.vercel.app"},{"type":"wordmark","text":"TRACE","small":true},{"type":"lines","scale":"m","items":["Questions?"]},{"type":"source","text":"trace-atlas-gules.vercel.app · open it yourself, it is live"}],"cues":["Leave the QR up during Q&A so judges can open the live site.","Q&A lead: backup slides follow (→), or press G for the overview."],"layout":"split"},{"id":"qa-backup","act":"V","speaker":"S4","seconds":0,"theme":"void","layout":"center","blocks":[{"type":"kicker","text":"Q&A backup"},{"type":"lines","scale":"m","items":["Backtest by drug · Afghanistan test · methods · impact · roadmap"]}],"cues":["Only for answering questions. Jump with G (overview) to the slide you need."]},{"id":"backtest","act":"V","speaker":"S4","seconds":0,"theme":"atlas","blocks":[{"type":"kicker","text":"Backtest · trained through 2019, predicting 2020–{{counts.latest_year}}"},{"type":"compare","items":[{"label":"LightGBM hurdle","value":"{{metrics.hurdle_auc}}","pct":88,"tone":"up","note":"AUC, corridor activation"},{"label":"Same as last year","value":"0.82","pct":82,"tone":"dim","note":"AUC, persistence baseline"},{"label":"PPML gravity baseline","value":"{{metrics.gravity_auc}}","pct":58,"tone":"dim","note":"AUC, same corridors, same years"}]},{"type":"viz","viz":{"kind":"bars","size":"sm","max":1,"items":[{"label":"Meth","value":0.96,"text":"0.96","tone":"on"},{"label":"Heroin","value":0.92,"text":"0.92","tone":"on"},{"label":"Cannabis","value":0.89,"text":"0.89","tone":"on"},{"label":"Cocaine","value":0.79,"text":"0.79","tone":"on"}]},"caption":"Our model's AUC by drug, same 2020–2024 test"},{"type":"sub","text":"Routes are sticky, so “same as last year” is the honest baseline, and we beat it on all three measures: AUC, volume ranking (Spearman {{metrics.spearman}} vs 0.48) and growth calls (precision@20 {{metrics.precision_at_20}} vs 0.42). A corridor shift shows up a year ahead, not after a nine-year wait for prevalence data."}],"cues":["Say the persistence number out loud: 0.82. Beating 'same as last year' is the real test, and we clear it on all three metrics.","Don't say 'our model is accurate'. Say 'here is our model against the field standard, on held-out years'.","Then translate it: a year of warning against a nine-year wait. That is the number that matters to a health ministry.","The baseline existing at all is the credibility move."]},{"id":"afghan","act":"V","speaker":"S4","seconds":0,"theme":"atlas","blocks":[{"type":"kicker","text":"The test we wrote down before we had the answer"},{"type":"lines","scale":"m","items":["One prespecified model.","Reported whichever way it came out."]},{"type":"shot","sid":"experiment","aspect":"16/10","maxvh":26,"caption":"Experiment — the prespecified retrospective model, its uncertainty, and every input traced to its source","spec":"Experiment / Retrospective study, 1440×960."},{"type":"statgrid","compact":true,"items":[{"value":"0.0195","label":"homicides per 100,000, per unit rise in log seizures","source":"country and seizure-year fixed effects, clustered SE","viz":{"kind":"ci","est":0.0195,"lo":-0.213,"hi":0.252,"min":-0.3,"max":0.3}},{"value":"0.869","label":"p-value","source":"95% interval [−0.213, 0.252] — it spans zero"},{"value":"1,428","label":"country-years behind the estimate","source":"144 countries, seizure years 2006–2022"}]},{"type":"source","text":"A retrospective ecological association, not a causal effect and not a forecast test. Seizures reflect enforcement and reporting. The product says all of this on the screen itself."}],"cues":["This is the slide that proves we are not selling you something.","We committed to the test in the spec, then published the interval and the p-value.","The interval spans zero. Say that out loud — do not hide it in the chart.","Hand to the next slide: so what did we do about it?"]},{"id":"methods","act":"V","speaker":"S4","seconds":0,"theme":"atlas","blocks":[{"type":"kicker","text":"How we got these numbers"},{"type":"lines","scale":"m","items":["Four claims, and exactly how we tested each one."]},{"type":"methods","items":[{"claim":"The route forecast works","how":"Trained on 2007–2019 (8,242 corridor-years), then predicted 2020–2024 (3,170) blind. Scored with AUC, Spearman and precision@20, against a PPML gravity model and a “same as last year” baseline on the identical split.","result":"AUC 0.88","detail":"gravity 0.58 · last year 0.82"},{"claim":"It catches real shocks","how":"Trained only through 2021, applied the 2022 opium ban as a 95% cultivation cut, forecast 2023, then compared with what actually happened.","result":"9 of 13 corridors","detail":"SE Asia share: 13.9% predicted, 13.4% actual"},{"claim":"Routes carry a burden","how":"Grouped countries by their role on 234 documented UNODC corridors and compared UNODC drug-use surveys and World Bank homicide rates between groups. Cross-sectional: where the burden sits, not what caused it.","result":"3.5× · 2.5×","detail":"cocaine use · homicide"},{"claim":"Routes cause later harm","how":"Written into the spec before the data: a logistic model asking whether route exposure predicts a 20%+ rise in homicide or HIV within three years, beyond vulnerability alone. Cross-validated by holding out whole countries. 4,186 country-years.","result":"Not supported","tone":"dim","detail":"CV AUC 0.705 without exposure, 0.712 with"}]},{"type":"source","text":"Data: World Bank Indicators API (24 indicators, 217 economies, 1960–2025), UNODC seizures 2006–2024 and drug-use surveys, Harm Reduction International 2008–2024, GI-TOC OC Index. Full method and every number: backend/README.md in the project repository."}],"cues":["Frame it as: before we show results, here is exactly how we tested them.","Row by row, one sentence each: blind backtest, natural experiment, cross-sectional comparison, prespecified test.","If asked about leakage: strict time split, and the gravity baseline on the same split scores 0.58. If we were leaking, it would be inflated too.","On the last row, say what we changed because of it: the risk score keeps exposure, vulnerability and protection as three columns, because being on a route without services is the danger, not the route alone.","If pressed on why exposure points the wrong way: seizure-based exposure also tracks enforcement capacity. Concede it before they raise it."]},{"id":"transit","act":"V","speaker":"S4","seconds":0,"theme":"void","blocks":[{"type":"kicker","text":"And it lands on people who never chose it"},{"type":"ratios","items":[{"value":"3.5×","label":"more cocaine use in countries on documented trafficking routes","viz":{"kind":"bars","size":"big","max":1.6,"items":[{"label":"On a route","value":1.52,"text":"1.52%","tone":"on"},{"label":"Off route","value":0.43,"text":"0.43%","tone":"off"}]},"note":"Cocaine use prevalence · UNODC WDR 2026 annex 1.2"},{"value":"2.5×","label":"more homicide in route countries than in destination-only countries","viz":{"kind":"bars","size":"big","max":3.2,"items":[{"label":"Route","value":3.0,"text":"3.0","tone":"on"},{"label":"Destination only","value":1.2,"text":"1.2","tone":"off"}]},"note":"Homicides per 100,000 · World Bank VC.IHR.PSRC.P5"}]},{"type":"sub","text":"A trafficking route is not a line on a map. It is a country carrying a burden it did not create. Routes are not destiny, though: these are cross-sectional numbers, and our prospective homicide/HIV test was null once vulnerability was controlled."},{"type":"source","text":"TRACE exploratory analysis · UNODC WDR 2026 annex 1.2 + World Bank VC.IHR.PSRC.P5 · route roles from 234 documented UNODC corridors · cross-sectional, not causal"}],"cues":["Lead with the two multipliers: 3.5 times the cocaine use, 2.5 times the homicide. Then the line about the burden.","This is cross-sectional evidence, not a causal claim. Say that if you quote the numbers.","Name the asymmetry: the harm lands furthest from where the decisions get made.","Handoff is coming — set up the next line."],"handoff":"Here's what we built instead."},{"id":"impact","act":"V","speaker":"S4","seconds":0,"theme":"atlas","blocks":[{"type":"kicker","text":"Why targeting is the whole problem"},{"type":"statgrid","compact":true,"title":"The services were never there","items":[{"value":"97","label":"of 190 countries with injecting drug use have no needle exchange anywhere","viz":{"kind":"dots","count":190,"lit":97,"label":"one dot = one country"}},{"value":"5","label":"countries cover both needle exchange and opioid treatment well — home to 2% of people who inject","viz":{"kind":"dots","count":190,"lit":5}},{"value":"35","label":"syringes per person who injects, per year","viz":{"kind":"bars","size":"sm","max":200,"items":[{"label":"Reality","value":35,"text":"35","tone":"on"},{"label":"WHO target","value":200,"text":"200","tone":"off"}]}}]},{"type":"statgrid","compact":true,"title":"And the money is leaving","items":[{"value":"0.7%","label":"of HIV spending goes to harm reduction, though people who inject are 8% of new infections","viz":{"kind":"bars","size":"sm","max":8,"items":[{"label":"Share of spend","value":0.7,"text":"0.7%","tone":"on"},{"label":"Share of infections","value":8,"text":"8%","tone":"off"}]}},{"value":"77%","label":"of harm-reduction services severely disrupted in 2025, after HIV funding fell 18%","viz":{"kind":"meter","value":77,"max":100}},{"value":"+3,672","label":"HIV infections modelled in one year from the 2025 funding cuts, in nine countries","viz":{"kind":"dots","count":3672,"per":50,"label":"one dot = 50 infections"}}]},{"type":"sub","text":"With less money and gaps this wide, <em>where</em> the next clinic goes decides how many infections it prevents. Today that call is made without a forecast. TRACE gives it one."},{"type":"source","text":"HRI Global State of Harm Reduction 2025 · WHO · UNAIDS, April 2025 · International Journal of Drug Policy, 2026"}],"cues":["Read two numbers, not six. 97 countries, and 0.7% of the money.","Then the pivot: the money is shrinking and the siting decision is being made blind.","Do NOT claim predictive targeting is proven. It isn't — see the Q&A sheet. Claim the alternative is worse."]},{"id":"social-good","act":"V","speaker":"S4","seconds":0,"theme":"atlas","blocks":[{"type":"kicker","text":"AI for social good · who acts on a forecast"},{"type":"lines","scale":"m","items":["One early warning.","Four ways to get ahead of the harm."]},{"type":"list","columns":4,"numbered":true,"items":[{"title":"Healthcare","text":"HIV and hepatitis C testing, clinics and opioid agonist therapy placed where a corridor is opening — a year ahead in the backtest, instead of waiting nine years for prevalence data."},{"title":"Prevention","text":"Naloxone, needle exchange and outreach stocked before a new supply arrives, not after the first overdose cluster."},{"title":"Public safety","text":"Police and first responders get advance notice to carry naloxone and route people to treatment instead of cells. TRACE points them at harm, never at where enforcement is weak."},{"title":"Governments and funders","text":"With harm-reduction funding falling, ministries and donors can put scarce money where risk is rising — and check the source behind every score."}]},{"type":"viz","viz":{"kind":"stack","total":100,"items":[{"label":"exposure: harm-weighted drug traffic","value":45,"tone":1},{"label":"vulnerability: youth jobs, poverty, inequality, health spend","value":35,"tone":3},{"label":"missing protection: harm-reduction services","value":20,"tone":4}],"label":"The risk score all four rely on, out of 100 · weights set openly, not fitted"}},{"type":"source","text":"Every use rests on the same public, sourced risk score and the same design rule: forecasts point at harm, not at people."}],"cues":["This is the social-good slide. Walk the four columns left to right, one sentence each.","Public safety: stress that it is about naloxone and treatment, not arrests. We never show where enforcement is weakest.","Land on funders: the money is shrinking, so where it goes matters more than ever."]},{"id":"model","act":"V","speaker":"S4","seconds":0,"theme":"atlas","blocks":[{"type":"kicker","text":"Two models, and we report both"},{"type":"pipeline","steps":[{"step":"BASELINE","title":"PPML gravity","text":"Poisson pseudo-maximum-likelihood, the standard in trade economics. GDP, population, distance, contiguity, price gap."},{"step":"MAIN","title":"LightGBM hurdle","text":"(a) will this corridor be active next year, (b) how much moves if it is. Lagged volume, cultivation upstream, governance, logistics, OC Index, conflict. 46 features per route-year."},{"step":"EXPLAIN","title":"SHAP per corridor","text":"Every predicted shift comes with its drivers, in plain language, on the map."}]},{"type":"source","text":"Santos Silva & Tenreyro (2006) · Ke et al. (2017) · Lundberg & Lee (2017)"}],"cues":["The hurdle structure exists because most corridors are zero in most years. Say that — it shows you understand your own data.","SHAP is what turns a prediction into something a health ministry can act on."]},{"id":"six-screens","act":"V","speaker":"S4","seconds":0,"theme":"atlas","blocks":[{"type":"kicker","text":"Every view, one ⌘K"},{"type":"shotgrid","items":[{"sid":"risk-board","title":"RISK BOARD","text":"217-country risk ranking with exposure, vulnerability, protection and trend","spec":"Fresh production capture · snapshot 27 Sept 2026, 12:18 UTC."},{"sid":"country-screen","title":"COUNTRY","text":"Ecuador profile — risk components, prevention coverage and source-year labels","spec":"Fresh production capture · snapshot 27 Sept 2026, 12:18 UTC."},{"sid":"simulator","title":"SCENARIOS","text":"Colombia coca reduction scenario; modeled changes, not policy forecasts","spec":"Fresh production capture · snapshot 27 Sept 2026, 12:18 UTC."},{"sid":"livewire","title":"LIVE WIRE","text":"Connected public-event feed and classification","spec":"Fresh production capture · snapshot 27 Sept 2026, 12:18 UTC."},{"sid":"market-board","title":"MARKETS","text":"Country-filtered price history; coverage varies by series","spec":"Fresh production capture · snapshot 27 Sept 2026, 12:18 UTC."},{"sid":"experiment","title":"EXPERIMENT","text":"Prespecified retrospective study; uncertainty interval crosses zero","spec":"Fresh production capture · snapshot 27 Sept 2026, 12:18 UTC."},{"sid":"health-evidence","title":"HEALTH EVIDENCE","text":"Four evidence domains; 213 published source records","spec":"Fresh production capture · snapshot 27 Sept 2026, 12:18 UTC."},{"sid":"people","title":"PEOPLE","text":"Cited public claims at country level — not live location intelligence","spec":"Fresh production capture · snapshot 27 Sept 2026, 12:18 UTC."}]}],"cues":["Name them fast — eight views in sixteen seconds.","The point is breadth: this is a product, not a notebook.","Everything is keyboard-driven — ⌘K goes anywhere.","The full navigation also has Health Evidence and a source-bounded People appendix. Do not pitch People as operational intelligence: it shows cited public claims at country level, never live locations, private addresses or weak routes."]},{"id":"commands","act":"V","speaker":"S4","seconds":0,"theme":"atlas","blocks":[{"type":"commandline","items":[{"cmd":"COL <GO>","out":"Colombia 2025 · risk 62.8 · harm-reduction coverage · every figure sourced and dated"},{"cmd":"COMPARE COL PER","out":"62.8 against 71.4 · side by side"},{"cmd":"SHOCK COL CULTIVATION -50%","out":"25 corridors change · 20 risk scores move"}]},{"type":"sub","text":"Free text is parsed into typed commands, each with a confidence value. Anything a judge can type, the workspace answers — and refuses, visibly, what it has no data for."}],"cues":["Read one command aloud, not all three.","Every one of these is verified working in the shipped app.","Hand off: 'None of this works without the data underneath it.'"],"handoff":"None of this works without the data underneath it."},{"id":"roadmap","act":"V","speaker":"S4","seconds":0,"theme":"atlas","blocks":[{"type":"kicker","text":"Where this goes"},{"type":"roadmap","items":[{"when":"Now","what":"{{status.shipped_short}}"},{"when":"+3 months","what":"Team-label real headlines + external Reflex validation, fentanyl module, ACLED conflict events"},{"when":"+6 months","what":"Wastewater and EUDA price feeds, weekly retrain, per-country alert subscriptions"},{"when":"+12 months","what":"Deployment with a harm-reduction partner in one transit corridor, measured against real service placement"}]}],"cues":["Read the dates as a plan, not a promise.","One sentence per row, maximum."]}]},"data":{"project":{"name":"TRACE","one_liner":"A Bloomberg terminal for the global drug trade that predicts where the next drug crisis will hit, before it arrives.","tagline":"Early warning for the countries that never chose to be on the route."},"counts":{"indicators":"24","economies":"217","ids_cases":"2.3M","corridors":"676","oc_index":"193","hri":"197","risk_countries":"217","latest_year":"2024","first_year":"2011","sources":"8","map_first_year":"2006","map_last_observed":"2024","map_forecast_year":"2025"},"metrics":{"hurdle_auc":"0.88","gravity_auc":"0.58","afghan_hit":"9/13","sea_base":"5%","sea_pred":"14%","sea_actual":"13%","train_through":"2019","afghan_train_through":"2021","spearman":"0.58","precision_at_20":"0.48","afghan_right":"9","afghan_of":"13"},"charts":{"afghan":{"series":[{"id":"afg_cultivation","label":"Afghanistan","unit":"ha","points":[{"x":2015,"y":183000},{"x":2016,"y":201000},{"x":2017,"y":328000},{"x":2018,"y":263000},{"x":2019,"y":163000},{"x":2020,"y":224000},{"x":2021,"y":177000},{"x":2022,"y":233000},{"x":2023,"y":10800},{"x":2024,"y":12800},{"x":2025,"y":10200}]},{"id":"mmr_cultivation","label":"Myanmar","unit":"ha","points":[{"x":2015,"y":55500},{"x":2017,"y":41000},{"x":2018,"y":37300},{"x":2019,"y":33100},{"x":2020,"y":29500},{"x":2021,"y":30200},{"x":2022,"y":40100},{"x":2023,"y":47100},{"x":2024,"y":45200},{"x":2025,"y":53100}]}],"ban_year":2022,"title":"Afghanistan 2022 opium ban"}},"provenance":{"built_from":"defaults","metrics":"README.md (live run)","afghan":"contracts/fixtures/afghan_ban.json"},"people":{"total":3099,"organizations":229,"convicted":2031,"charged":456,"sanctioned":536,"reported":76},"screenshots":{"route-map":"screenshots/route-map.png","experiment":"screenshots/experiment.png","country-screen":"screenshots/country-screen.png","experiment-afghan":"screenshots/experiment-afghan.png","livewire":"screenshots/livewire.png","market-board":"screenshots/market-board.png","risk-board":"screenshots/risk-board.png","simulator":"screenshots/simulator.png","health-evidence":"screenshots/health-evidence.png","people":"screenshots/people.png"},"placeholders":[],"status":{"shipped":[{"label":"Spec, docs, handoff","owner":"planning session","status":"done"},{"label":"API contract + fixtures","owner":"backend","status":"done (`contracts/`)"},{"label":"backend scaffold","owner":"backend","status":"done (uv, Python 3.11, `trace` CLI)"},{"label":"World Bank ingest","owner":"backend","status":"done; now read from the SQLite v2 archive (24 indicators, 217 economies, 1960-2025)"},{"label":"external ingest (UNODC, OC Index, HRI, CEPII)","owner":"backend","status":"done (IDS 2.3M cases, WDR annex, OC Index x3, HRI 197 countries, CEPII; see BLOCKERS.md)"},{"label":"edges + confidence","owner":"backend","status":"done (676 corridors x 2011-2024, seizure-anchored allocation, 6-signal confidence)"},{"label":"route models + backtest + Afghan ban test","owner":"backend","status":"done, retrained on SQLite archive (hurdle AUC 0.88 vs gravity 0.58; Afghan ban 9/13 corridors, SEA share 5%->14% pred vs 13% actual)"},{"label":"spillover risk","owner":"backend","status":"done (217 countries x 2008-2025, HRI per edition; hypothesis not supported)"},{"label":"SQLite v2 migration","owner":"backend","status":"done (archive read-only + `derived.sqlite`; DuckDB removed)"},{"label":"Reflex (own System One model)","owner":"backend","status":"v0.2 shipped as the Live Wire classifier: 98% event type, 82% destination (mock 52%), ECE 0.02; see [REFLEX_SPEC.md](docs/REFLEX_SPEC.md)"},{"label":"export + API","owner":"backend","status":"done (precomputed JSON, FastAPI, contract tests)"},{"label":"Live Wire (mock Jev)","owner":"backend","status":"done (JevClassifier + mock, GDELT poller with replay fallback, REST + WS)"},{"label":"shock simulator","owner":"backend","status":"done (structured + plain-English shocks, command bar)"},{"label":"API deployment","owner":"backend","status":"done: live at https://trace-api-six.vercel.app (Vercel; keyword Live Wire classifier, backlog replay)"},{"label":"People API","owner":"backend","status":"done (`/api/people`, `/countries`, `/network`, `/{person_id}`; parity with the frontend route handlers)"},{"label":"Route evidence API","owner":"backend","status":"done (`/api/route-evidence`: 51 direct reported pairs, 234 interpreted corridors, 4 narrative claims; `evidence_ids`/`kg_basis` on route edges)"},{"label":"Evidence drilldown API","owner":"backend","status":"done (`/api/evidence/*`: 3,995 research and market values traced to formula, inputs and original cells; health and CDC overdose with the required labels)"},{"label":"Frontend shell + map","owner":"frontend","status":"done: live at https://trace-atlas-gules.vercel.app (atlas map with year slider and 2025 forecast, full-screen mode, drug filters, estimated local flows)"},{"label":"Country Screen + Risk Board","owner":"frontend","status":"done (risk watchlist and board, country inspector with routes, indicators, harm reduction and briefing)"},{"label":"Simulator, Live Wire, Market Board","owner":"frontend","status":"done (Scenarios tab with policy dates, Live Wire feed, Markets tab; Experiment tab for the Afghan ban test)"},{"label":"Merged database (`database_new`)","owner":"backend","status":"done: `backend/scripts/merge_databases.py` = canonical archive + derived API tables + route-evidence seeds (76 tables); uploaded to the team Drive folder as `database_new.sqlite.gz` + `database_new.json`"}],"pending":[],"frontend_built":true,"shipped_short":"Pipeline, models, backtests and Live Wire shipped; the site and the API are live in production","shipped_count":21,"pending_count":0},"git":{"sha":"93a51a3","subject":"deck: rebuild after Atlas flow refresh","when":"2026-09-27T10:46:06-04:00","count":"327"},"built_at":"2026-09-27 14:50 UTC","screenshot_snapshot":{"app":"trace-0.1.0","snapshot_utc":"2026-09-27 12:18 UTC"}}};